    "tool/README.md": "# __PACKAGE_NAME__\n\nAGH tool starter. Requires Node.js 24.10 or later and matching AGH package builds.\n\n__SETUP_GUIDE__\n\nUse `@agnes/host/author-testkit` for author tests. See the [SDK import map](https://github.com/AgnesAI-Labs/agnes-harness/blob/main/docs/extend/imports.md) for helpers, contracts and service kind tokens.\n\nAfter activation, ask a new session to call __TOOL_NAME__ with {\"message\":\"hello\"}. Inspect the tool record for the structured result. Update effect and replay metadata when adding I/O.\n",
    "tool/package.json": "{\n  \"name\": \"__PACKAGE_NAME__\",\n  \"version\": \"0.1.0\",\n  \"type\": \"module\",\n  \"license\": \"Apache-2.0\",\n  \"engines\": {\n    \"node\": \">=24.10\"\n  },\n  \"exports\": \"./dist/index.js\",\n  \"files\": [\n    \"dist\",\n    \"client\",\n    \"skills\",\n    \"mcp.json\"\n  ],\n  \"scripts\": {\n    \"build\": \"tsc -p tsconfig.json\",\n    \"test\": \"node --import tsx --test\"\n  },\n  \"dependencies\": {\n    \"@agnes/plugin-runtime\": \"0.0.0\",\n    \"@agnes/extension-api\": \"^5.0.0\",\n    \"@sinclair/typebox\": \"0.34.33\"\n  },\n  \"devDependencies\": {\n    \"typescript\": \"7.0.2\",\n    \"@types/node\": \"26.4.1\",\n    \"tsx\": \"4.23.13\",\n    \"@agnes/host\": \"0.0.0\"\n  },\n  \"agnes\": {\n    \"plugins\": [\n      {\n        \"export\": \"main\",\n        \"apiRange\": \"^5.0.0\",\n        \"id\": \"ext:__PACKAGE_NAME__/main\",\n        \"inject\": [\n          \"tools\"\n        ],\n        \"capabilities\": {}\n      }\n    ],\n    \"hostProvidedExternals\": {\n      \"@agnes/plugin-runtime\": \"0.0.0\",\n      \"@agnes/extension-api\": \"^5.0.0\",\n      \"@sinclair/typebox\": \"0.34.33\"\n    },\n    \"provides\": [\n      \"tool\"\n    ]\n  }\n}\n",
    "tool/src/index.ts": "import { type Context, defineAgnesPlugin, defineTool, readOnlyTool, toolError } from '@agnes/plugin-runtime'\nimport { Type } from '@sinclair/typebox'\n\nexport const echo = defineTool({\n  name: '__TOOL_NAME__',\n  description: 'Echo a nonempty message.',\n  parameters: Type.Object({ message: Type.String() }, { additionalProperties: false }),\n  result: Type.Object({ message: Type.String() }, { additionalProperties: false }),\n  meta: readOnlyTool,\n  async execute({ message }, ctx) {\n    ctx.signal.throwIfAborted()\n    if (!message.trim()) return toolError('A nonempty message is required')\n    // Pass ctx.signal to asynchronous work you add; release per-call resources in finally.\n    return { content: [{ type: 'text', text: message }], structured: { message } }\n  },\n})\n\nexport const main = defineAgnesPlugin({\n  apply(ctx: Context) {\n    ctx.tools.register(echo)\n  },\n})\n",
    "tool/test/plugin.test.mjs": "import assert from 'node:assert/strict'\nimport { test } from 'node:test'\nimport { fileURLToPath } from 'node:url'\nimport { createPluginTestHost } from '@agnes/host/author-testkit'\nimport { echo, main } from '../dist/index.js'\n\ntest('register, invoke, reject invalid inputs and unload', async () => {\n  const host = await createPluginTestHost(main, {\n    packageDir: fileURLToPath(new URL('../', import.meta.url)),\n  })\n  try {\n    assert.deepEqual((await host.invoke(echo.name, { message: 'hello' })).structured, { message: 'hello' })\n    assert.equal((await host.invoke(echo.name, { message: '' })).isError, true)\n    await assert.rejects(host.invoke(echo.name, { message: 1 }), /Invalid arguments/)\n    const cancelled = new AbortController()\n    cancelled.abort(new DOMException('Stopped', 'AbortError'))\n    await assert.rejects(host.invoke(echo.name, { message: 'hello' }, cancelled.signal), /Stopped/)\n  } finally {\n    await host.dispose()\n  }\n  assert.equal(host.tools.size, 0)\n})\n",
